        Select select = (Select) CCJSqlParserUtil.parse(new StringReader(sql));

        if (select.getSelectBody() instanceof PlainSelect) {
            PlainSelect plainSelect = (PlainSelect) select.getSelectBody();
            if (offset != null) {
                plainSelect.setOffset(offset);
            }
            if (limit != null) {
                plainSelect.setLimit(limit);
            }
        } else if (select.getSelectBody() instanceof SetOperationList) {
            SetOperationList setOperationList = (SetOperationList) select.getSelectBody();
            if (offset != null) {
                setOperationList.setOffset(offset);
            }
            if (limit != null) {
                setOperationList.setLimit(limit);
            }
        } else {
            throw new PageException("分页语句必须是Select查询!");
        }

        return select.toString();
    } catch (JSQLParserException e) {
        throw new PageException("不支持该SQL转换为分页查询!", e);
